mapper.select:
SELECT id, gmt_create AS gmtCreate, gmt_modify AS gmtModify, type_id AS typeId, case_type AS caseType, name, gender, birthday, passport, json_str AS jsonStr, contract_str AS contractStr, contract_file_path AS contractFilePath, letter_file_path AS letterFilePath, `956path` AS form956Path, customer_signature AS customerSignature, application_data AS applicationData, ai_consult_content AS aiConsultContent, adviser_id AS adviserId, official_id AS officialId, mara_id AS maraId, service_order_id AS serviceOrderId, str_state AS strState FROM b_portal_list WHERE 1 = 1
AND id = #{id}
AND type_id = #{typeId}
AND case_type = #{caseType}
AND str_state IN ('01', '02', '02A', '02B', '02C', '02D', '03', '03A', '04', '05', '06', '06A', '06B', '06C', '07', '07A', '07B', '08', '09', '010', '010A', '010B', '010C', '010D', '010E', '010F', '010G', '011', '011A', '012')
AND str_state = '013'
AND str_state = #{strState}
AND (str_state IS NULL OR str_state NOT IN ('01', '02'))
AND name LIKE '%${keyword}%'
AND name LIKE CONCAT('%', #{name}, '%')
AND adviser_id = #{adviserId}
AND adviser_id IN ( SELECT id FROM tb_adviser WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{adviserRegionId} OR parent_id = #{adviserRegionId} ) )
AND official_id = #{officialId}
AND official_id IN ( SELECT id FROM b_official WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{officialRegionId} OR parent_id = #{officialRegionId} ) )
AND mara_id = #{maraId}
ORDER BY id DESC LIMIT #{offset}, #{rows};

SELECT count(*)
FROM b_portal_list
WHERE 1 = 1

    AND id = #{id}


    AND type_id = #{typeId}


    AND case_type = #{caseType}




        AND str_state IN ('01', '02', '02A', '02B', '02C', '02D', '03', '03A', '04', '05',
            '06', '06A', '06B', '06C', '07', '07A', '07B', '08', '09', '010', '010A', '010B', '010C',
            '010D', '010E', '010F', '010G', '011', '011A', '012')


        AND str_state = '013'


        AND str_state = #{strState}




    AND (str_state IS NULL OR str_state NOT IN ('01', '02'))


    AND name LIKE '%${keyword}%'


    AND name LIKE CONCAT('%', #{name}, '%')


    AND adviser_id = #{adviserId}


    AND adviser_id IN (
        SELECT id FROM tb_adviser WHERE region_id IN (
            SELECT id FROM tb_region WHERE id = #{adviserRegionId} OR parent_id = #{adviserRegionId}
        )
    )


    AND official_id = #{officialId}


    AND official_id IN (
        SELECT id FROM b_official WHERE region_id IN (
            SELECT id FROM tb_region WHERE id = #{officialRegionId} OR parent_id = #{officialRegionId}
        )
    )


    AND mara_id = #{maraId}

;

SELECT id, gmt_create AS gmtCreate, gmt_modify AS gmtModify, type_id AS typeId, case_type AS caseType, name, gender, birthday, passport, json_str AS jsonStr, contract_str AS contractStr, contract_file_path AS contractFilePath, letter_file_path AS letterFilePath, `956path` AS form956Path, customer_signature AS customerSignature, application_data AS applicationData, ai_consult_content AS aiConsultContent, adviser_id AS adviserId, official_id AS officialId, mara_id AS maraId, service_order_id AS serviceOrderId, str_state AS strState FROM b_portal_list WHERE id = #{id, jdbcType=INTEGER}
AND name LIKE CONCAT('%', #{name}, '%')
AND adviser_id = #{adviserId}
AND adviser_id IN ( SELECT id FROM tb_adviser WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{adviserRegionId} OR parent_id = #{adviserRegionId} ) )
AND official_id = #{officialId}
AND official_id IN ( SELECT id FROM b_official WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{officialRegionId} OR parent_id = #{officialRegionId} ) )
AND mara_id = #{maraId}
;
